# Deterministic readability repairs, with no changes to mathematical answer sets.
import re
POLISH=json.loads((ROOT/'audits/L09-text-polish-map.json').read_text())
def prose(s):
 s=re.sub(r'[A-Za-z]+',lambda m:POLISH.get(m.group(),m.group()),s)
 s=re.sub(r'([,;:])(?=[^\s])',r'\1 ',s)
 s=re.sub(r'\.(?=[A-Za-z])','. ',s)
 s=re.sub(r'(?<=[A-Za-z])(?=\()', ' ',s)
 s=re.sub(r'(?<=\))(?=[A-Za-z])',' ',s)
 s=re.sub(r'(?<=[a-z])(?=[0-9])',' ',s)
 s=re.sub(r'(?<=[0-9])(?=[A-Za-z])',' ',s)
 # Preserve scientific identifiers such as q1,theta1 andmatrixI3 after prose number spacing.
 s=re.sub(r'\b([qvxyzJRI]) ([0-9])',r'\1\2',s)
 s=re.sub(r'\b(theta|θ) ([0-9])',r'\1\2',s)
 s=re.sub(r'(?<=[A-Za-z])(?=[θωτδεΔ])', ' ', s)
 s=re.sub(r'([θωτδεΔ])(?=[A-Za-z])', r'\1 ', s)
 s=s.replace('θ dot','θdot').replace('Δ t','Δt').replace('δ q','δq').replace('δ x','δx')
 s=re.sub(r'(?<=[A-Za-z])(?=\[)', ' ', s)
 s=re.sub(r'(?<=\])(?=[A-Za-z])', ' ', s)
 s=re.sub(r'\bc ([123])', r'c\1', s)
 return re.sub(r' +',' ',s).strip()
def polish_obj(x):
 if isinstance(x,str):return prose(x)
 if isinstance(x,list):return [polish_obj(v) for v in x]
 if isinstance(x,dict):return {k:polish_obj(v) for k,v in x.items()}
 return x
for q in Q:
 for key in ['stem','subtopic','assumptions','solution']:q[key]=polish_obj(q[key])
 for option in q['options']:option['text']=prose(option['text'])
 for cite in q['citations']:
  for key in ['locator','evidenceText']:cite[key]=prose(cite[key])
for c in C:
 for key in ['title','description','examinationAngles']:c[key]=polish_obj(c[key])
if __name__=='__main__':persist(False)
